import boto3
import os
from typing import Dict, Any, List, Optional

def get_summary_field(expense_doc: Dict[str, Any], field_type: str) -> Optional[str]:
    """Extracts a specific summary field from the Textract expense document."""
    for field in expense_doc.get("SummaryFields", []):
        if field.get("Type", {}).get("Text") == field_type:
            return field.get("ValueDetection", {}).get("Text")
    return None

def get_line_item_field(line_item: Dict[str, Any], field_type: str) -> Optional[str]:
    """Extracts a specific field from a line item."""
    for field in line_item.get("LineItemExpenseFields", []):
        if field.get("Type", {}).get("Text") == field_type:
            return field.get("ValueDetection", {}).get("Text")
    return None

def extract_receipt_data(file_path: str) -> Dict[str, Any]:
    """
    Extracts merchant, tax, total, and items from a receipt image file.

    Args:
        file_path: The path to the receipt image file.

    Returns:
        A dictionary containing the extracted receipt data.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found at {file_path}")

    # Provider-identifying signal: Boto3 SDK for AWS Textract
    textract_client = boto3.client(
        "textract",
        # Credentials and region are typically configured via environment variables
        # (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_REGION) or an IAM role.
    )

    with open(file_path, "rb") as document_file:
        document_bytes = document_file.read()

    # Provider-identifying signal: AWS Textract's analyze_expense operation
    response = textract_client.analyze_expense(
        Document={"Bytes": document_bytes}
    )

    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": [],
    }

    if not response.get("ExpenseDocuments"):
        return extracted_data

    # Typically, a single receipt image results in one ExpenseDocument
    expense_doc = response["ExpenseDocuments"][0]

    # Extract summary fields
    extracted_data["merchant"] = get_summary_field(expense_doc, "VENDOR_NAME")
    extracted_data["tax"] = get_summary_field(expense_doc, "TAX")
    extracted_data["total"] = get_summary_field(expense_doc, "TOTAL")

    # Extract line items
    items: List[Dict[str, Optional[str]]] = []
    for group in expense_doc.get("LineItemGroups", []):
        for line_item in group.get("LineItems", []):
            item_details = {
                "description": get_line_item_field(line_item, "ITEM"),
                "price": get_line_item_field(line_item, "PRICE"),
                "quantity": get_line_item_field(line_item, "QUANTITY"),
            }
            items.append(item_details)

    extracted_data["items"] = items

    return extracted_data
